// Golfing Shane's variant of 272 chars https://shadertoy.com/view/l3dyWX
//        loopless variant of 253 chars https://shadertoy.com/view/MXtyWj
// more readable version below


//  -10 by SnoopethDuckDuck

void mainImage(out vec4 O, vec2 u){

    vec2 R = iResolution.xy,
         p = u/R.y  * mat2(9,-9,9,9),                                // scaling + 45° rotation
         I = ceil(p),                                                // grid
         f = I - p - .5,                                             // cell local coordinates
         a = abs(f),
         d = min(a, a.y) - .25;                                      // distance to diamond

    int i = int( I + I.y*3. ) % 5;                                   // diag rotation

    O = 1. - min( abs(d) ,                                           // small diamonds
                  i>3 ? R : max( abs( (i>0 && i<3 ?-f:f) + f.y )*.7, // cross
                                 d )                                 // minus diamonds hole
                ).x * R.yyyy/20.;
}





/** // 228 chars:  -2 by SnoopethDuckDuck

void mainImage(out vec4 O, vec2 u){

    vec2 R = iResolution.xy,
         p = u/R.y  * mat2(9,-9,9,9),                                      // scaling + 45° rotation
         I = ceil(p),                                                      // grid
         f = p - I +.5,                                                    // cell local coordinates
         a = abs(f);                                                       // cell symmetry

    float d = min(a.x, a.y) - .25;                                         // distance to diamond
    int   i = int( I + I.y*3. ) % 5;                                       // diag rotation

    O =  1. - min( abs(d) ,                                                // small diamonds
                   i>3 ? 1e5 : max( abs( (i>0 && i<3 ?-f:f).x + f.y )*.7 , // cross
                                    d )                                    // minus diamonds hole
                 )*R.yyyy/20.;
}





/** // 249 chars

void mainImage(out vec4 O, vec2 u){

    vec2 R = iResolution.xy,
         U = 9.*u/R.y, 
         p = U + vec2(-U.y,U),
         I = ceil(p),
         f = p - I +.5;
    p = abs( abs(f) - .5 );

    int   i = int( I + I.y*3. ) % 5; 
     i > 0 && i < 3 ? f.x = -f.x : 0.;
    float d = max(p.x, p.y) - .25;

    O = 1.- min( abs(d) , 
                 i>3 ? 1e5 : max( abs(f.x+f.y)*.7 , -d )
               )*R.yyyy/20.;  
}





/** // 488 chars brute Shane version 

void mainImage(out vec4 O, vec2 u){

    // Setup.
    vec2 R = iResolution.xy,
         p = 10.*u/R.y,  
         //p = 7.*(u - u.yx*vec2(1, -1))/R.y,  // Rotation.                               
         I = floor(p); // ID.

    // Smoothing factor.
    float sf = 10./R.y;

    // Local coordinates.
    p -= I + .5;

    // Background grid for clarity.
    float grid = max(abs(p.x), abs(p.y)) - .5;
    grid = abs(grid) - .01;


    // Repeat five cell diagonal line pattern: 
    // Left, right, right, left, empty.
    // 1, 2, 2, 1, 0

    int index = int(I.x + I.y*3.)%5; 

    // If the index is 1 or 2, flip the line to the right.
    if(index == 1 || index == 2) p.x = -p.x;

    // Edge width.
    float ew = .015;

    // Diagonal line.
    float ln = dot(p, vec2(sqrt(.5)));
    ln = abs(ln) - ew;     


    // Repeat for the four vertices.
    p = abs(p) - 1./2.;

    p = abs(p);
    float d = max(p.x, p.y) - .5/2.;  

    // Using the squares to restrict line length.
    ln = max(ln, -d);

    // If the index is four, don't render a diagonal line.
    if(index==4) ln = 1e5;


    // Square cell boundaries.
    d = abs(d) - ew;


    // Combining the square boundaries and line.
    d = min(d, ln);


    // Render the background grid.
    O = mix(vec4(1, .1, .2, 0), vec4(0), smoothstep(0., sf, grid));

    // Render the pattern.
    O = mix(vec4(1), O, smoothstep(0., sf, d));

    // Rough gamma.
    O = sqrt(O);       
}
/**/
